// === DOM элементы ===
const regionDetails = document.getElementById('region-details');
const symbolicsContent = document.querySelector('.symbolics-content');
const loadingScreen = document.getElementById('loading-screen');
const titleScreen = document.getElementById('title-screen');
const mainContent = document.getElementById('main-content');
const progressBar = document.getElementById('progress-bar');
const loadingText = document.getElementById('loading-text');
const mapImage = document.getElementById('map-image');

// === Сообщения загрузки ===
const loadingMessages = [
  "Карта в печати...",
  "Загружаем географические открытия...",
  "Работаем на территории...",
  "Возвращаемся к истокам..."
];

// === Параллакс для фона ===
function initParallax() {
  if ('ontouchstart' in window) return;
  const slavicPattern = document.querySelector('.slavic-pattern');
  const titleBackground = document.querySelector('.title-background');
  function handleMouseMove(e) {
    const xAxis = (window.innerWidth / 2 - e.pageX) / 25;
    const yAxis = (window.innerHeight / 2 - e.pageY) / 25;
    const transform = `translate(${xAxis}px, ${yAxis}px)`;
    if (slavicPattern && !loadingScreen.classList.contains('hidden')) {
      slavicPattern.style.transform = transform;
    }
    if (titleBackground && !titleScreen.classList.contains('hidden')) {
      titleBackground.style.transform = transform;
    }
  }
  document.addEventListener('mousemove', handleMouseMove);
}

// === Функция: подсветить пункт в списке ===
function highlightListItem(regionId) {
  document.querySelectorAll('.region-item').forEach(item => {
    if (item.dataset.region === regionId) {
      item.classList.add('active');
    } else {
      item.classList.remove('active');
    }
  });
}

// === Функция: снять подсветку ===
function clearHighlight() {
  document.querySelectorAll('.region-item').forEach(item => {
    item.classList.remove('active');
  });
}

// === Функция: смена изображения карты ===
function handleRegionHover(regionId) {
  if (regionId && regions[regionId]) {
    mapImage.src = regions[regionId].hoverImage;
  } else {
    mapImage.src = 'images/map-base.png';
  }
}

// === Функция: показ символики ===
function showSymbolics(id) {
  regionDetails.classList.remove('hidden');
  symbolicsContent.innerHTML = '';
  const cfg = symbolicsConfig[id];
  if (!cfg) return;
  if (Array.isArray(cfg)) {
    cfg.forEach(item => {
      const el = document.createElement('div');
      el.className = 'symbolic-card';
      el.innerHTML = `
        <img src="images/${item.flag}" alt="${item.name} флаг">
        <div class="symbolic-label flag-label">Флаг</div>
        <img src="images/${item.gerb}" alt="${item.name} герб">
        <div class="symbolic-label">Герб</div>
      `;
      symbolicsContent.appendChild(el);
    });
  } else {
    const el = document.createElement('div');
    el.className = 'symbolic-card';
    el.innerHTML = `
      <img src="images/${cfg.flag}" alt="Флаг ${id}">
      <div class="symbolic-label flag-label">Флаг</div>
      <img src="images/${cfg.gerb}" alt="Герб ${id}">
      <div class="symbolic-label">Герб</div>
    `;
    symbolicsContent.appendChild(el);
  }
}

// === Функция: скрыть символику ===
function hideSymbolics() {
  regionDetails.classList.add('hidden');
}

// === Анимация загрузки ===
function startLoading() {
  let progress = 0;
  let msgIdx = 0;
  const dur = 5000;
  const int = 50;
  const step = 100 / (dur / int);
  const msgInt = dur / loadingMessages.length;

  const prog = setInterval(() => {
    progress += step;
    progressBar.style.width = Math.min(progress, 100) + '%';
    if (progress >= 100) {
      clearInterval(prog);
      loadingScreen.classList.add('hidden');
      titleScreen.classList.remove('hidden');
      setTimeout(() => {
        titleScreen.classList.add('hidden');
        mainContent.classList.remove('hidden');

        // === [НОВОЕ] Показываем кнопку "К тестам" ===
        const testsBtn = document.getElementById('tests-btn');
        if (testsBtn) testsBtn.classList.remove('hidden');
        // ===========================================

      }, 3000);
    }
  }, int);

  const msg = setInterval(() => {
    if (msgIdx < loadingMessages.length) {
      loadingText.style.opacity = '0';
      setTimeout(() => {
        loadingText.textContent = loadingMessages[msgIdx];
        loadingText.style.opacity = '1';
      }, 300);
      msgIdx++;
    } else {
      clearInterval(msg);
    }
  }, msgInt);
}

// === Инициализация главной страницы ===
document.addEventListener('DOMContentLoaded', () => {
  startLoading();
  initParallax();

  const regionItems = document.querySelectorAll('.region-item');
  const regionAreas = document.querySelectorAll('.region-area');

  // Наведение на список
  regionItems.forEach(item => {
    const id = item.dataset.region;
    item.addEventListener('mouseenter', () => {
      handleRegionHover(id);
      showSymbolics(id);
      highlightListItem(id);
    });
    item.addEventListener('mouseleave', () => {
      const isOverArea = Array.from(regionAreas).some(area => area.matches(':hover'));
      if (!isOverArea) {
        handleRegionHover(null);
        hideSymbolics();
        clearHighlight();
      }
    });
  });

  // Наведение на карту
  regionAreas.forEach(area => {
    const id = area.dataset.region;
    area.addEventListener('mouseenter', () => {
      handleRegionHover(id);
      showSymbolics(id);
      highlightListItem(id);
    });
    area.addEventListener('mouseleave', () => {
      const isOverItem = Array.from(regionItems).some(item => item.matches(':hover'));
      if (!isOverItem) {
        handleRegionHover(null);
        hideSymbolics();
        clearHighlight();
      }
    });
  });

  // Клик → переход
  [...regionItems, ...regionAreas].forEach(el => {
    const id = el.dataset.region;
    if (id) {
      el.addEventListener('click', (e) => {
        e.preventDefault();
        window.location.href = `region-${id}.html`;
      });
    }
  });
});

