// === ИНИЦИАЛИЗАЦИЯ СТРАНИЦЫ РЕГИОНА ===
if (currentRegion) {
  document.addEventListener('DOMContentLoaded', () => {
    const container = document.getElementById('map-container');
    const mapContentWrapper = document.getElementById('map-content-wrapper');
    const mapImage = document.getElementById('region-map');
    const infoPanel = document.getElementById('info-panel');
    const infoContent = document.getElementById('info-content');
    const closeBtn = document.getElementById('close-info');

    if (!container || !mapContentWrapper || !mapImage) return;

    // Получаем данные региона
    const landmarks = regionLandmarks[currentRegion] || [];
    const positions = regionMarkerPositions[currentRegion] || [];

    // Создание меток
    positions.forEach(([id, left, top]) => {
      const landmark = landmarks.find(l => l.id === id);
      if (!landmark) return;

      const marker = document.createElement('div');
      marker.className = `map-marker ${landmark.type}`;
      marker.style.left = `${left}%`;
      marker.style.top = `${top}%`;
      marker.dataset.category = landmark.type;
      marker.dataset.id = id;

      marker.addEventListener('click', (e) => {
        e.stopPropagation();
        showInfoPanel(landmark);
      });

      mapContentWrapper.appendChild(marker);
    });

    // === ЛОГИКА ФИЛЬТРОВ ===
    function updateMarkersVisibility() {
      const activeCategories = Array.from(document.querySelectorAll('.filter-item.active'))
        .map(item => item.dataset.category);
      
      document.querySelectorAll('.map-marker').forEach(marker => {
        const category = marker.dataset.category;
        marker.style.display = activeCategories.includes(category) ? 'block' : 'none';
      });
    }

    // Обновление при старте
    updateMarkersVisibility();

    // Обновление при клике на фильтр
    document.querySelectorAll('.filter-item').forEach(item => {
      item.addEventListener('click', () => {
        item.classList.toggle('active');
        updateMarkersVisibility();
      });
    });

    // Закрытие панели информации
    if (closeBtn) {
      closeBtn.addEventListener('click', () => {
        infoPanel.classList.add('hidden');
      });
    }

    document.addEventListener('click', (e) => {
      if (!infoPanel.contains(e.target) && !e.target.closest('.map-marker')) {
        infoPanel.classList.add('hidden');
      }
    });

    // === МАСШТАБИРОВАНИЕ КАРТЫ ===
    let scale = 1;
    const SCALE_MIN = 1;
    const SCALE_MAX = 3;
    let isDragging = false;
    let startX, startY, translateX = 0, translateY = 0;

    function constrainTranslate() {
      if (scale <= 1) {
        translateX = 0;
        translateY = 0;
        return;
      }
      const containerRect = container.getBoundingClientRect();
      const imgWidth = containerRect.width * scale;
      const imgHeight = containerRect.height * scale;
      const maxX = (imgWidth - containerRect.width) / 2;
      const maxY = (imgHeight - containerRect.height) / 2;
      translateX = Math.max(-maxX, Math.min(maxX, translateX));
      translateY = Math.max(-maxY, Math.min(maxY, translateY));
    }

    container.addEventListener('wheel', (e) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? -0.1 : 0.1;
      const newScale = Math.min(SCALE_MAX, Math.max(SCALE_MIN, scale + delta));
      
      const rect = container.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const offsetX = (mouseX - rect.width / 2) * (newScale - scale);
      const offsetY = (mouseY - rect.height / 2) * (newScale - scale);

      scale = newScale;
      translateX += offsetX;
      translateY += offsetY;

      constrainTranslate();
      
      // Применяем трансформацию к обёртке, а не к картинке
      mapContentWrapper.style.transform = `translate(${translateX}px, ${translateY}px) scale(${scale})`;
    });

    container.addEventListener('mousedown', (e) => {
      if (scale <= 1) return;
      isDragging = true;
      startX = e.clientX - translateX;
      startY = e.clientY - translateY;
      container.style.cursor = 'grabbing';
      e.preventDefault();
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      translateX = e.clientX - startX;
      translateY = e.clientY - startY;
      constrainTranslate();
      mapContentWrapper.style.transform = `translate(${translateX}px, ${translateY}px) scale(${scale})`;
    });

    window.addEventListener('mouseup', () => {
      if (isDragging) {
        isDragging = false;
        container.style.cursor = '';
      }
    });

    // === ОТОБРАЖЕНИЕ ИНФОРМАЦИИ ===
    function showInfoPanel(landmark) {
      let html = `<h2>${landmark.name}</h2>`;

      // Герб и флаг (только для исторических)
      if (landmark.type === 'historical' && (landmark.flag || landmark.coatOfArms)) {
        html += `<div class="info-section"><h3>Герб и флаг</h3><div class="info-images">`;
        if (landmark.flag) html += `<img src="${landmark.flag}" alt="Флаг">`;
        if (landmark.coatOfArms) html += `<img src="${landmark.coatOfArms}" alt="Герб">`;
        html += `</div></div>`;
      }

      // Изображения
      if (landmark.images && landmark.images.length > 0) {
        html += `<div class="info-section"><h3>Изображения</h3><div class="info-images">`;
        landmark.images.forEach(img => {
          html += `<img src="${img}" alt="">`;
        });
        html += `</div></div>`;
      }

      // Геопозиция
      html += `
        <div class="info-section">
          <h3>Геопозиция</h3>
          <div class="info-geo">${landmark.geo} (<a href="${landmark.geoLink}" target="_blank">карта</a>)</div>
        </div>
      `;

      // Описание
      html += `<div class="info-section"><h3>Описание</h3><p>${landmark.description}</p></div>`;

      infoContent.innerHTML = html;
      infoPanel.classList.remove('hidden');
    }
  });
}

