// === ЗАГРУЗКА ПРОГРЕССА ИЗ LOCALSTORAGE ===
function loadTestProgress() {
  Object.keys(testQuestions).forEach(region => {
    const saved = localStorage.getItem(`test_${region}`);
    if (saved) {
      const data = JSON.parse(saved);
      // [ИЗМЕНЕНО] — Всегда считаем, что тест можно пройти, метки не отслеживаются
      updateTestBlock(region, data.correct, data.completed);
    }
  });
}

// === ОБНОВЛЕНИЕ ВИДА БЛОКА ТЕСТА ===
function updateTestBlock(region, correctCount, completed) {
  const block = document.querySelector(`.test-block[data-region="${region}"]`);
  if (!block) return;
  
  const correctEl = block.querySelector('.correct-count');
  if (correctEl) correctEl.textContent = correctCount;
  
  const startBtn = block.querySelector('.start-test-btn');
  if (!startBtn) return;
  
  // [ИЗМЕНЕНО] — Кнопка всегда активна, тест можно пройти заново
  if (completed) {
    block.classList.add('completed');
    startBtn.disabled = false;
    startBtn.title = 'Пройти тест ещё раз';
    startBtn.textContent = '▶';
  } else {
    startBtn.disabled = false;
    startBtn.title = 'Начать тест';
    startBtn.textContent = '▶';
  }
}

