// === ПРОВЕРКА ДОСТУПНОСТИ ФИНАЛЬНОГО ТЕСТА ===
function checkFinalTestAvailability() {
  // [ИЗМЕНЕНО] — Проверяем, что все 5 региональных тестов пройдены (есть класс .completed)
  const regions = ['crimea', 'kherson', 'zaporozhye', 'donetsk', 'lugansk'];
  const allCompleted = regions.every(region => {
    const block = document.querySelector(`.test-block[data-region="${region}"]`);
    return block && block.classList.contains('completed');
  });
  
  const finalBlock = document.querySelector('.test-block[data-region="final"]');
  if (!finalBlock) return;
  
  const btn = finalBlock.querySelector('.start-test-btn');
  
  if (allCompleted) {
    // Все 5 тестов пройдены — открываем финальный
    finalBlock.classList.remove('locked');
    finalBlock.dataset.locked = 'false';
    if (btn) {
      btn.disabled = false;
      btn.title = 'Начать общий тест';
      btn.textContent = '▶';
    }
  } else {
    // Не все тесты пройдены — блокируем
    finalBlock.classList.add('locked');
    finalBlock.dataset.locked = 'true';
    if (btn) {
      btn.disabled = true;
      btn.title = 'Пройдите все региональные тесты сначала';
      btn.textContent = '🔒';
    }
  }
}

// === НАСТРОЙКА ОБРАБОТЧИКОВ СОБЫТИЙ ===
function setupEventListeners() {
  document.querySelectorAll('.start-test-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const block = e.target.closest('.test-block');
      if (!block) return;
      
      const region = block.dataset.region;
      showConfirmModal(region);
    });
  });
  
  // [ОБНОВЛЕНО] — Обработка кликов по обоим модальным окнам
  document.querySelectorAll('.modal').forEach(modal => {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.classList.add('hidden');
        // Если закрыли окно завершения — сбрасываем регион
        if (modal.id === 'finish-confirm-modal') {
          pendingFinishRegion = null;
        }
      }
    });
  });
  
  // [ЗАКОММЕНТИРОВАНО] — Слушатель для отслеживания меток отключён
  /*
  window.addEventListener('storage', (e) => {
    if (e.key && e.key.startsWith('viewed_markers_')) {
      updateMarkerCounts();
    }
  });
  */
}

// === ПОКАЗ МОДАЛЬНОГО ОКНА ПОДТВЕРЖДЕНИЯ ===
function showConfirmModal(region) {
  const modal = document.getElementById('confirm-modal');
  const timerLimit = document.getElementById('timer-limit');
  if (timerLimit) timerLimit.textContent = region === 'final' ? '30' : '10';
  currentTest = region;
  if (modal) modal.classList.remove('hidden');
}

// === ПОДТВЕРЖДЕНИЕ НАЧАЛА ТЕСТА ===
function confirmStartTest() {
  const modal = document.getElementById('confirm-modal');
  if (modal) modal.classList.add('hidden');
  if (!currentTest) return;
  
  // [ИЗМЕНЕНО] — Если тест уже был пройден, очищаем предыдущие результаты перед новым запуском
  const savedTest = localStorage.getItem(`test_${currentTest}`);
  if (savedTest) {
    const testData = JSON.parse(savedTest);
    if (testData.completed) {
      localStorage.removeItem(`test_${currentTest}`);
    }
  }
  
  startTestLogic(currentTest);
}

// === ОТМЕНА НАЧАЛА ТЕСТА ===
function cancelStartTest() {
  const modal = document.getElementById('confirm-modal');
  if (modal) modal.classList.add('hidden');
  currentTest = null;
}

// === [НОВОЕ] ОБРАБОТЧИК КНОПКИ "ЗАВЕРШИТЬ ТЕСТ" — с подтверждением ===
// Заменяем старую функцию finishTest на новую с модальным окном
function finishTest(region) {
  pendingFinishRegion = region;
  const modal = document.getElementById('finish-confirm-modal');
  if (modal) modal.classList.remove('hidden');
}

// === [НОВОЕ] ПОДТВЕРЖДЕНИЕ ЗАВЕРШЕНИЯ ТЕСТА ===
function confirmFinishTest() {
  const modal = document.getElementById('finish-confirm-modal');
  if (modal) modal.classList.add('hidden');
  
  if (!pendingFinishRegion) return;
  
  const block = document.querySelector(`.test-block[data-region="${pendingFinishRegion}"]`);
  const timerEl = block?.querySelector('.test-timer');
  
  finishTestLogic(pendingFinishRegion, block, timerEl || null);
  pendingFinishRegion = null;
}

// === [НОВОЕ] ОТМЕНА ЗАВЕРШЕНИЯ ТЕСТА ===
function cancelFinishTest() {
  const modal = document.getElementById('finish-confirm-modal');
  if (modal) modal.classList.add('hidden');
  pendingFinishRegion = null;
}

// === ОСНОВНАЯ ЛОГИКА ЗАПУСКА ТЕСТА ===
function startTestLogic(region) {
  const block = document.querySelector(`.test-block[data-region="${region}"]`);
  if (!block) return;
  
  // Скрываем предыдущие результаты при новом запуске
  const existingResult = block.querySelector('.test-result');
  if (existingResult) existingResult.remove();
  
  const statsEl = block.querySelector('.test-stats');
  const questionsWrapper = block.querySelector('.test-questions-wrapper');
  
  // СКРЫВАЕМ статистику текущего блока
  if (statsEl) statsEl.classList.add('hidden');
  
  // Показываем вопросы ТОЛЬКО текущего блока
  if (questionsWrapper) {
    questionsWrapper.classList.remove('hidden');
    const container = questionsWrapper.querySelector('.questions-container');
    if (container) container.innerHTML = '';
  }
  
  generateQuestions(region);
  
  const timerEl = block.querySelector('.test-timer');
  const timeLimit = region === 'final' ? 30 * 60 : 10 * 60;
  if (timerEl) {
    timerEl.classList.remove('warning');
    startTimer(timeLimit, timerEl);
  }
  
  testStartTime = Date.now();
  userAnswers[region] = {};
  
  const finishBtn = block.querySelector('.finish-test-btn');
  if (finishBtn) finishBtn.classList.remove('hidden');
}

// === ГЕНЕРАЦИЯ ВОПРОСОВ ===
function generateQuestions(region) {
  const container = document.querySelector(`.test-block[data-region="${region}"] .questions-container`);
  if (!container) return;
  container.innerHTML = '';
  
  let questions = testQuestions[region] || [];
  
  if (region === 'final') {
    // [ИЗМЕНЕНО] — Генерируем вопросы для финального теста и сохраняем их
    finalTestQuestions = [];
    ['crimea', 'kherson', 'zaporozhye', 'donetsk', 'lugansk'].forEach(reg => {
      const shuffled = [...(testQuestions[reg] || [])].sort(() => 0.5 - Math.random());
      finalTestQuestions.push(...shuffled.slice(0, 6));
    });
    finalTestQuestions.sort(() => 0.5 - Math.random());
    questions = finalTestQuestions;
  }
  
  questions.forEach((q, index) => {
    const card = document.createElement('div');
    card.className = 'question-card';
    card.dataset.index = index;
    // [НОВОЕ] — Сохраняем правильный ответ в data-атрибут
    card.dataset.correctAnswer = q.correct;
    
    card.innerHTML = `
      <div class="question-text">${index + 1}. ${q.question}</div>
      <div class="answers-list">
        ${q.answers.map((answer, i) => `
          <label class="answer-option">
            <input type="radio" name="q${region}_${index}" value="${i}" class="answer-radio">
            <span class="answer-text">${answer}</span>
          </label>
        `).join('')}
      </div>
    `;
    
    container.appendChild(card);
    
    card.querySelectorAll('.answer-radio').forEach(radio => {
      radio.addEventListener('change', (e) => {
        card.querySelectorAll('.answer-option').forEach(opt => opt.classList.remove('selected'));
        const selectedOpt = e.target.closest('.answer-option');
        if (selectedOpt) selectedOpt.classList.add('selected');
        userAnswers[region][index] = parseInt(e.target.value);
      });
    });
  });
}

// === ТАЙМЕР ТЕСТА ===
function startTimer(seconds, timerEl) {
  timeRemaining = seconds;
  updateTimerDisplay(timerEl);
  
  clearInterval(testTimer);
  testTimer = setInterval(() => {
    timeRemaining--;
    updateTimerDisplay(timerEl);
    
    if (timeRemaining === 120 && timerEl) timerEl.classList.add('warning');
    
    if (timeRemaining <= 0) {
      clearInterval(testTimer);
      const block = timerEl?.closest('.test-block');
      if (block) {
        const region = block.dataset.region;
        finishTestLogic(region, block, timerEl);
      }
    }
  }, 1000);
}

function updateTimerDisplay(timerEl) {
  if (!timerEl) return;
  const mins = Math.floor(timeRemaining / 60);
  const secs = timeRemaining % 60;
  timerEl.textContent = `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}

// === ЗАВЕРШЕНИЕ ТЕСТА — МГНОВЕННЫЕ ИТОГИ ===
// [ОБНОВЛЕНО] — finishTestLogic остаётся без изменений, вызывает finishTest через модальное окно
function finishTestLogic(region, block, timerEl = null) {
  if (testTimer) {
    clearInterval(testTimer);
    testTimer = null;
  }
  
  // [ИЗМЕНЕНО] — Используем сохраненные вопросы для финального теста
  const questions = region === 'final' 
    ? finalTestQuestions 
    : (testQuestions[region] || []);
  
  let correctCount = 0;
  const questionCards = block.querySelectorAll('.question-card');
  const totalQuestions = questionCards.length;
  
  questionCards.forEach((card, index) => {
    const userAnswer = userAnswers[region]?.[index];
    // [ИЗМЕНЕНО] — Получаем правильный ответ из data-атрибута
    const correctAnswer = parseInt(card.dataset.correctAnswer);
    
    // [ИЗМЕНЕНО] — Считаем только если дан ответ
    if (userAnswer !== undefined && userAnswer === correctAnswer) {
      correctCount++;
      card.classList.add('correct');
    } else if (userAnswer !== undefined) {
      card.classList.add('incorrect');
    } else {
      // Не отвеченный вопрос
      card.classList.add('unanswered');
    }
    
    // Показываем правильный ответ
    if (correctAnswer !== undefined) {
      const options = card.querySelectorAll('.answer-option');
      if (options[correctAnswer]) options[correctAnswer].classList.add('correct');
    }
    
    card.querySelectorAll('input').forEach(input => input.disabled = true);
  });
  
  if (timerEl) timerEl.classList.add('hidden');
  const finishBtn = block.querySelector('.finish-test-btn');
  if (finishBtn) finishBtn.classList.add('hidden');
  
  // [ИЗМЕНЕНО] — Передаем correctCount и totalQuestions
  showTestResult(block, region, correctCount, totalQuestions);
  saveTestProgress(region, correctCount, true);
  
  if (region !== 'final') checkFinalTestAvailability();
}

// === ПОКАЗ РЕЗУЛЬТАТОВ ===
function showTestResult(block, region, correct, total) {
  const questionsContainer = block.querySelector('.questions-container');
  if (!questionsContainer) return;
  
  // [ИСПРАВЛЕНО] — correct/total, а не total/correct (было Infinity%)
  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
  let message = '';
  if (percentage >= 90) message = 'Отлично! Вы прекрасно знаете регион! 🏆';
  else if (percentage >= 70) message = 'Хороший результат! 👍';
  else if (percentage >= 50) message = 'Неплохо, но есть куда расти 📚';
  else message = 'Рекомендуем изучить материалы региона ещё раз 🔍';
  
  const resultDiv = document.createElement('div');
  resultDiv.className = 'test-result';
  resultDiv.innerHTML = `
    <h3>Результаты теста</h3>
    <div class="test-result-score">${correct}/${total} (<span class="percentage">${percentage}%</span>)</div>
    <div class="test-result-text">${message}</div>
    
    <button class="test-result-btn" onclick="location.reload()">Свернуть</button>
  `;
  // <button class="test-result-btn retake-btn" onclick="retakeTest('${region}')">Пройти ещё раз</button>
  
  questionsContainer.parentNode?.insertBefore(resultDiv, questionsContainer.nextSibling);
}

// === ПОВТОРНОЕ ПРОХОЖДЕНИЕ ТЕСТА ===
function retakeTest(region) {
  localStorage.removeItem(`test_${region}`);
  
  const block = document.querySelector(`.test-block[data-region="${region}"]`);
  if (block) {
    const resultDiv = block.querySelector('.test-result');
    if (resultDiv) resultDiv.remove();
    
    block.classList.remove('completed');
    updateTestBlock(region, 0, false);
    
    const statsEl = block.querySelector('.test-stats');
    const questionsWrapper = block.querySelector('.test-questions-wrapper');
    if (statsEl) statsEl.classList.remove('hidden');
    if (questionsWrapper) questionsWrapper.classList.add('hidden');
    
    const timerEl = block.querySelector('.test-timer');
    if (timerEl) {
      timerEl.classList.remove('warning');
      const timeLimit = region === 'final' ? 30 * 60 : 10 * 60;
      updateTimerDisplay(timerEl);
    }
  }
  
  console.log(`[Retake] Тест "${region}" сброшен, можно пройти заново`);
}

// === СОХРАНЕНИЕ ПРОГРЕССА ===
function saveTestProgress(region, correctCount, completed) {
  const data = {
    correct: correctCount,
    completed: completed,
    timestamp: Date.now()
  };
  localStorage.setItem(`test_${region}`, JSON.stringify(data));
}

